const input = $input.first().json || {};
const workflow = input.workflow || {};
const execution = input.execution || {};
const error = input.error || input;
const nodes = Array.isArray(workflow.nodes) ? workflow.nodes : [];
const getAssignments = nodeName => {
  const node = nodes.find(n => n.name === nodeName);
  return node?.parameters?.assignments?.assignments || [];
};
const cfg = {};
for (const a of getAssignments('Configurar Cliente')) {
  if (a && a.name) cfg[a.name] = a.value;
}
const clean = value => String(value || '').replace(/^[(https?://[^]]+)]([^)]*)$/, '$1').trim();
const splitDestinos = value => String(value || '').split(/[
;,]+/).map(v => v.trim()).filter(Boolean);
const nodeName = error.node?.name || error.nodeName || input.lastNodeExecuted || execution.lastNodeExecuted || '';
const mainMessage = error.message || input.message || 'Erro sem mensagem';
const falhas = [];
falhas.push({ node: nodeName, mensagem: mainMessage, stack: error.stack || '' });
if (Array.isArray(input.errors)) {
  for (const e of input.errors) {
    falhas.push({ node: e.node?.name || e.nodeName || '', mensagem: e.message || String(e), stack: e.stack || '' });
  }
}
const dedup = new Set();
const falhasUnicas = falhas.filter(f => {
  const key = [f.node, f.mensagem].join('|');
  if (dedup.has(key)) return false;
  dedup.add(key);
  return true;
});
const workflowNome = workflow.name || input.workflowName || 'Workflow desconhecido';
const workflowId = workflow.id || input.workflowId || '';
const executionId = execution.id || input.executionId || '';
const executionUrl = execution.url || input.executionUrl || '';
const detalhes = falhasUnicas.map((f, index) => {
  const local = f.node ? ' no node ' + f.node : '';
  return String(index + 1) + '.' + local + ': ' + String(f.mensagem || 'Erro sem mensagem').slice(0, 900);
}).join(String.fromCharCode(10));
const texto = [
  String.fromCodePoint(0x1F6A8) + ' *ALERTA*',
  'Ola Willyan, o sistema falhou.',
  '',
  '*Workflow:* ' + workflowNome + (workflowId ? ' (' + workflowId + ')' : ''),
  executionId ? '*Execucao:* ' + executionId : '',
  '*Falhas:*',
  detalhes || '1. Erro sem detalhes no payload do n8n.',
  executionUrl ? '' : '',
  executionUrl || '',
].filter(v => v !== '').join(String.fromCharCode(10));
const diag = { workflow: workflowNome, workflowId, executionId, node: nodeName, falhas: falhasUnicas.map(f => ({ node: f.node, mensagem: f.mensagem })), numeroErrosConfigurado: Boolean(cfg.numeroErros) };
console.log('[NOTICIAS_V3_ERRO] ' + JSON.stringify(diag));
const numeroErros = splitDestinos(cfg.numeroErros);
if (!numeroErros.length) return [{ json: { enviado: false, motivo: 'numeroErros vazio no workflow que falhou', texto, diagnostico: diag } }];
const base = clean(cfg.evolutionUrl || 'http://evolution-api:8080').replace(//$/, '');
const instancia = clean(cfg.instancia || '');
const apikey = clean(cfg.evolutionApiKey || cfg.apikey || '');
if (!base || !instancia || !apikey) return [{ json: { enviado: false, motivo: 'Configuracao de envio incompleta no workflow que falhou', texto, diagnostico: { ...diag, temBase: Boolean(base), temInstancia: Boolean(instancia), temApiKey: Boolean(apikey) } } }];
const http = async ({ method = 'GET', url, headers = {}, body, json = false, timeout = 30000 }) => {
  if (this && this.helpers && this.helpers.httpRequest) return await this.helpers.httpRequest({ method, url, headers, body, json, timeout });
  if (typeof fetch !== 'function') throw new Error('Nenhum cliente HTTP disponivel no Code node');
  const init = { method, headers: { ...headers }, signal: AbortSignal.timeout(timeout) };
  if (body !== undefined) {
    init.body = typeof body === 'string' ? body : JSON.stringify(body);
    if (!init.headers['Content-Type'] && !init.headers['content-type']) init.headers['Content-Type'] = 'application/json';
  }
  const response = await fetch(url, init);
  const text = await response.text();
  if (!response.ok) throw new Error(method + ' ' + url + ' -> HTTP ' + response.status + ': ' + text.slice(0, 300));
  return json ? (text ? JSON.parse(text) : null) : text;
};
const resultados = [];
for (const raw of numeroErros) {
  const number = /^[0-9]+(?:-[0-9]+)?@g\.us$/.test(raw) ? raw : raw.replace(/D/g, '');
  if (!number) {
    resultados.push({ destino: raw, enviado: false, erro: 'Destino vazio/invalido' });
    continue;
  }
  try {
    const resp = await http({ method: 'POST', url: base + '/message/sendText/' + encodeURIComponent(instancia), headers: { apikey }, body: { number, text: texto, linkPreview: false }, json: true, timeout: 30000 });
    resultados.push({ destino: raw, enviado: true, messageId: resp?.key?.id || resp?.messageId || '' });
  } catch (e) {
    resultados.push({ destino: raw, enviado: false, erro: e.message });
  }
}
return [{ json: { enviado: resultados.some(r => r.enviado), texto, resultados, diagnostico: diag } }];
